/// `tests/boolean/bsection/P9`
#[test]
fn p9() -> DrawResult<()> {
    let mut d = Draw::new();
    d.dset(&["SCALE", "100"])?;
    d.plane(&["pl", "0", "0", "0", "0", "0", "1"])?;
    d.mkface(&["fa", "pl", "-1", "1", "-1", "1"])?;
    d.dset(&["azval", "20"])?;
    d.dset(&["dipval", "80"])?;
    d.dset(&["radval", "0.5"])?;
    d.dset(&["az", "azval*pi/180"])?;
    d.dset(&["dip", "dipval*pi/180"])?;
    d.dset(&["dx", "sin(dip)*sin(az)"])?;
    d.dset(&["dy", "sin(dip)*cos(az)"])?;
    d.dset(&["dz", "cos(dip)"])?;
    d.dset(&["ux", "cos(az)"])?;
    d.dset(&["uy", "sin(az)"])?;
    d.dset(&["uz", "0"])?;
    d.circle(&["circ", "0.5", "0.5", "0", "dx", "dy", "dz", "ux", "uy", "uz", "radval"])?;
    d.plane(&["pl2", "0.5", "0.5", "0", "dx", "dy", "dz"])?;
    d.mkedge(&["edg", "circ"])?;
    d.wire(&["wir", "edg"])?;
    d.mkface(&["fb", "pl2", "wir"])?;
    d.bsection(&["result", "fa", "fb"])?;
    d.checkprops(&["result", "-l", "1"])?;
    d.checksection(&["result"])?;
    d.checkshape(&["result"])?;
    Ok(())
}

